    private int m_result;

    public int GetResultPartOne()
    {
        string[] rows = MyInput.Split('\n');
        List<Coord> junctionBoxes = [];
        
        //parse
        junctionBoxes.AddRange(rows.Select(row => row.Split(',').Select(int.Parse).ToArray()).Select(parts => new Coord(parts[0], parts[1], parts[2])));

        List<(Coord a, Coord b, double distance)> distances = [];
        
        //calculate distances
        for (int i = 0; i < junctionBoxes.Count; i++)
        {
            Coord currentBox = junctionBoxes[i];
            
            for (int j = i + 1; j < junctionBoxes.Count; j++)
            {
                Coord otherBox = junctionBoxes[j];

                double distance = Math.Sqrt(Math.Pow(currentBox.X - otherBox.X, 2) +
                                         Math.Pow(currentBox.Y - otherBox.Y, 2) +
                                         Math.Pow(currentBox.Z - otherBox.Z, 2));
                
                distances.Add((currentBox, otherBox, distance));
            }
        }

        distances = distances.OrderBy(distance => distance.distance).ToList();

        List<List<Coord>> groups = [];

        //make groups
        foreach ((Coord a, Coord b, double distance) value in distances[..1000])
        {
            List<Coord>? groupWithA = groups.FirstOrDefault(group => group.Any(coord => coord == value.a));
            List<Coord>? groupWithB = groups.FirstOrDefault(group => group.Any(coord => coord == value.b));
            
            if (groupWithA is not null && groupWithB is null)
            {
                groupWithA.Add(value.b);
            }
            else if (groupWithB is not null && groupWithA is null)
            {
                groupWithB.Add(value.a);
            }
            else if (groupWithB is not null && groupWithA is not null && !groupWithA.SequenceEqual(groupWithB))
            {
                foreach (Coord coord in groupWithB)
                {
                    groupWithA.Add(coord);
                }
                groups.Remove(groupWithB);
            }
            else if (groupWithA is null && groupWithB is null)
            {
                groups.Add([value.a, value.b]);
            }
        }
        
        return groups.OrderByDescending(g => g.Count).Take(3).Aggregate(1, (i, list) => i * list.Count);
    }
    
    public long GetResultPartTwo()
    {
        string[] rows = MyInput.Split('\n');
        List<Coord> junctionBoxes = [];
        
